unsigned int NaiveNativeTree_predict1(int const pX[64]) {
  unsigned short i = 0;
  while (!tree1[i].isLeaf) {
    if (pX[tree1[i].feature] <= tree1[i].split) {
      i = tree1[i].leftChild;
    } else {
      i = tree1[i].rightChild;
    }
  }
  return tree1[i].prediction;
}
