unsigned int NaiveNativeTree_predict3(int const pX[64]) {
  unsigned short i = 0;
  while (!tree3[i].isLeaf) {
    if (pX[tree3[i].feature] <= tree3[i].split) {
      i = tree3[i].leftChild;
    } else {
      i = tree3[i].rightChild;
    }
  }
  return tree3[i].prediction;
}
