unsigned int NaiveNativeTree_predict4(int const pX[64]) {
  unsigned short i = 0;
  while (!tree4[i].isLeaf) {
    if (pX[tree4[i].feature] <= tree4[i].split) {
      i = tree4[i].leftChild;
    } else {
      i = tree4[i].rightChild;
    }
  }
  return tree4[i].prediction;
}
