unsigned int NaiveNativeTree_predict18(int const pX[64]) {
  unsigned short i = 0;
  while (!tree18[i].isLeaf) {
    if (pX[tree18[i].feature] <= tree18[i].split) {
      i = tree18[i].leftChild;
    } else {
      i = tree18[i].rightChild;
    }
  }
  return tree18[i].prediction;
}
