unsigned int NaiveNativeTree_predict21(int const pX[64]) {
  unsigned short i = 0;
  while (!tree21[i].isLeaf) {
    if (pX[tree21[i].feature] <= tree21[i].split) {
      i = tree21[i].leftChild;
    } else {
      i = tree21[i].rightChild;
    }
  }
  return tree21[i].prediction;
}
